    "seasonNotes": "UK-grown apples are a key seasonal/storage option, but a particular apple's origin should be confirmed from the label.; Import origin evidence: UK orchard-fruit output increased in 2025, with overall orchard-fruit production up 3.9%; the source describes earlier picking and storage picking for apples in 2025. It does not provide a month-by-month import origin schedule for apples in this section.; Origin evidence strength: UK production trend documented for 2025; origin-by-month imports not established.; Verification: Verified — RHS fruit harvest and storage guidance",
