    "seasonNotes": "UK tomato supply shifts by season: the Netherlands was the largest exporter during summer 2023; in winter, imports from the Netherlands declined and southern European/North African supply, primarily Spain and Morocco, increased. This is a trade pattern, not a guaranteed origin for an individual item.; UK supply is available year-round but likely origin varies by season. Check the item's label for actual country; do not infer greenhouse heating or production method.; Import origin evidence: Summer (2023): Netherlands was the largest exporter of fresh tomatoes to the UK. Winter (2023): imports from the Netherlands fell; Spain and Morocco became more prominent.; Origin evidence strength: Strong for the documented 2023 pattern; future years and individual items may differ.; Verification: Partially verified — UK Food Security Report 2024 describes seasonal source shifts",
    "preservedOptions": "",
    "gapFiller": "",
    "notes": "RHS says tomatoes start ripening from mid-summer, with greenhouse crops generally earlier and continuing well into autumn. Do not infer heating status or retail origin. Imported-season note: The months describe a broad EU growing season, not a full import window. UK tomatoes can be produced and imported year-round; do not infer heated greenhouse status. Origin research update: UK tomato supply shifts by season: the Netherlands was the largest exporter during summer 2023; in winter, imports from the Netherlands declined and southern European/North African supply, primarily Spain and Morocco, increased. This is a trade pattern, not a guaranteed origin for an individual item. Domestic supply context uses UK Food Security Report 2024 data for 2023; it is annual/group-level evidence, not a monthly origin guarantee.; UK domestic supply context: Tomatoes as a group: UK production-to-supply ratio was 15% in 2023, indicating substantial import reliance. Seasonal trade patterns show Netherlands as the largest UK supplier in summer 2023, with Spain and Morocco more prominent in winter.; Sources: https://www.gov.uk/government/statistics/united-kingdom-food-security-report-2024/united-kingdom-food-security-report-2024-theme-2-uk-food-supply-sources",
